#define main legacy_main
#include "hausdorff-cuda/main.cu"
#undef main
#include <vector>
float directed_oracle(const std::vector<float2>&a,const std::vector<float2>&b){float largest=0;for(auto p:a){float smallest=std::numeric_limits<float>::max();for(auto q:b)smallest=std::min(smallest,hd(p,q));largest=std::max(largest,smallest);}return largest;}
int main(){int na=512,nb=768,repeat=10;std::vector<float2>a(na),b(nb);for(int i=0;i<na;i++)a[i]=make_float2(float((17*i+3)%1024)/1024.f,float((29*i+7)%1024)/1024.f);for(int i=0;i<nb;i++)b[i]=make_float2(float((31*i+11)%1024)/1024.f,float((43*i+19)%1024)/1024.f);float want[2]={directed_oracle(a,b),directed_oracle(b,a)},out[2],initial[2]={-1.f,-1.f};float2 *da,*db;float*dy;cudaMalloc(&da,na*8);cudaMalloc(&db,nb*8);cudaMalloc(&dy,8);cudaMemcpy(da,a.data(),na*8,cudaMemcpyHostToDevice);cudaMemcpy(db,b.data(),nb*8,cudaMemcpyHostToDevice);auto run=[&](){computeDistance<<<(na+255)/256,256>>>(da,db,dy,na,nb);computeDistance<<<(nb+255)/256,256>>>(db,da,dy+1,nb,na);};cudaMemcpy(dy,initial,8,cudaMemcpyHostToDevice);run();if(cudaDeviceSynchronize()!=cudaSuccess)return 2;
for(int trial=1;trial<=5;trial++){double total=0.;for(int j=0;j<repeat;j++){cudaMemcpy(dy,initial,8,cudaMemcpyHostToDevice);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();run();if(cudaDeviceSynchronize()!=cudaSuccess)return 2;total+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();}cudaMemcpy(out,dy,8,cudaMemcpyDeviceToHost);float err=fmaxf(fabsf(out[0]-want[0]),fabsf(out[1]-want[1]));bool correct=std::isfinite(out[0])&&std::isfinite(out[1])&&err<=1e-3f;char file[32];snprintf(file,sizeof(file),"trial_%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(out,4,2,f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.14g,\"correct\":%s,\"checked_values\":2,\"max_abs_error\":%.14g,\"timing_region\":\"mean_two_directional_kernels_excluding_reset\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":2,\"byte_order\":\"little\"}}\n",trial,total/repeat,correct?"true":"false",err,repeat,file);if(!correct)return 1;}cudaFree(da);cudaFree(db);cudaFree(dy);}
